#include "sensors.h"
#include <QtWidgets>
#include <cmath>
#include <limits>
class Plot:public QWidget{
public:
 std::vector<Sensor*> sources; Sensor* best=nullptr;
 Plot(){setMinimumHeight(250);}
 void paintEvent(QPaintEvent*)override{
 QPainter p(this);p.setRenderHint(QPainter::Antialiasing);p.fillRect(rect(),QColor("#101f32"));
 p.setPen(QColor("#9ab0c8"));p.drawText(22,30,QString::fromUtf8("ТОЧНОСТЬ И ЗОНА НЕОПРЕДЕЛЁННОСТИ"));
 double maximum=1;for(auto*s:sources)maximum=qMax(maximum,s->accuracy());
 for(int i=0;i<int(sources.size());i++){auto*s=sources[i];int y=70+i*56;p.setPen(QColor("#dfeaf4"));p.drawText(22,y,s->name());p.drawText(22,y+21,QString::number(s->accuracy(),'f',1)+" м");p.setBrush(s==best?QColor("#42e4d2"):QColor("#416080"));p.setPen(Qt::NoPen);p.drawRoundedRect(QRectF(170,y-12,(width()*0.43-170)*s->accuracy()/maximum,22),5,5);}
 QPointF c(width()*0.76,145);p.setBrush(Qt::NoBrush);for(int i=3;i>=1;i--){p.setPen(QPen(QColor("#29465f"),1,Qt::DashLine));p.drawEllipse(c,i*30,i*30);}if(best){p.setPen(QPen(QColor("#42e4d2"),2));double r=20+60*best->accuracy()/maximum;p.drawEllipse(c,r,r);p.setBrush(QColor("#42e4d2"));p.drawEllipse(c,5,5);}p.setPen(QColor("#9ab0c8"));p.drawText(QRectF(width()*0.56,245,width()*0.4,30),Qt::AlignCenter,QString::fromUtf8("Условный масштаб · погрешность, м"));
 }
};
